$adDailyCap=max(0,min(10,(int)settings_get('ad_daily_cap',getenv('AD_DAILY_CAP')?:0)));
$customAdsEnabled=filter_var(settings_get('custom_ads_enabled',getenv('CUSTOM_ADS_ENABLED')?:'0'),FILTER_VALIDATE_BOOLEAN);
$customAdsDefault=max(5,min(180,(int)settings_get('custom_ads_default',getenv('CUSTOM_ADS_DEFAULT')?:15)));

$partners=$pdo->query('SELECT id,name,code,active FROM partners ORDER BY active DESC,name,id')->fetchAll()?:[];
$advertisers=fs_monetization_advertisers($pdo);
$campaigns=fs_monetization_campaigns($pdo);
$assignments=$pdo->query('SELECT cp.*,c.name campaign_name,p.name partner_name FROM ad_campaign_partners cp JOIN ad_campaigns c ON c.id=cp.campaign_id JOIN partners p ON p.id=cp.partner_id ORDER BY cp.updated_at DESC,cp.id DESC')->fetchAll()?:[];
$ads=$pdo->query('SELECT id,title,campaign_id,ad_kind,lead_capture_enabled,active FROM custom_ads WHERE partner_id IS NULL ORDER BY active DESC,id DESC')->fetchAll()?:[];
$offerStats=$pdo->query("SELECT q.status,l.message_status,COUNT(*) total FROM promo_queue q JOIN ad_leads l ON l.id=q.reference_id AND q.reference_type='ad_lead' WHERE q.purpose='ad_offer' GROUP BY q.status,l.message_status ORDER BY q.status,l.message_status")->fetchAll()?:[];
$failedOffers=$pdo->query("SELECT q.id,q.attempts,q.updated_at,l.id lead_id,p.name partner_name,COALESCE(c.name,a.title) campaign_name FROM promo_queue q JOIN ad_leads l ON l.id=q.reference_id AND q.reference_type='ad_lead' JOIN partners p ON p.id=l.partner_id JOIN custom_ads a ON a.id=l.ad_id LEFT JOIN ad_campaigns c ON c.id=l.campaign_id WHERE q.purpose='ad_offer' AND q.status='error' AND l.status NOT IN ('duplicate','revoked','anonymized') AND l.expires_at>NOW() ORDER BY q.updated_at DESC LIMIT 50")->fetchAll()?:[];
$performance=$pdo->query("SELECT c.id,c.name,c.status,c.campaign_type,
    (SELECT COUNT(*) FROM ad_deliveries d WHERE d.campaign_id=c.id AND d.is_simulation=0) deliveries,
    (SELECT COUNT(*) FROM ad_deliveries d WHERE d.campaign_id=c.id AND d.is_simulation=0 AND d.qualified_view_at IS NOT NULL) completed_views,
    (SELECT COUNT(*) FROM ad_deliveries d WHERE d.campaign_id=c.id AND d.is_simulation=0 AND d.qualified_click_at IS NOT NULL) clicks,
    (SELECT COUNT(*) FROM ad_leads l WHERE l.campaign_id=c.id AND l.status NOT IN ('duplicate','revoked','anonymized')) leads,
    (SELECT COUNT(*) FROM ad_campaign_partners cp WHERE cp.campaign_id=c.id AND cp.status='active') active_partners
    FROM ad_campaigns c ORDER BY c.starts_at DESC,c.id DESC")->fetchAll()?:[];

$editAdvertiser=null;
if(isset($_GET['edit_advertiser']))foreach($advertisers as $candidate)if((int)$candidate['id']===(int)$_GET['edit_advertiser']){$editAdvertiser=$candidate;break;}
$editCampaign=null;
if(isset($_GET['edit_campaign']))foreach($campaigns as $candidate)if((int)$candidate['id']===(int)$_GET['edit_campaign']){$editCampaign=$candidate;break;}
$activeCampaigns=count(array_filter($campaigns,static fn(array $campaign):bool=>(string)$campaign['status']==='active'));
$activeAds=count(array_filter($ads,static fn(array $ad):bool=>(int)$ad['active']===1));
$queuedOffers=0;foreach($offerStats as $stat)if(in_array((string)$stat['status'],['pending','sending'],true))$queuedOffers+=(int)$stat['total'];

$campaignStatusLabels=['draft'=>'Rascunho','awaiting_payment'=>'Aguardando orçamento','active'=>'Ativa','paused'=>'Pausada','exhausted'=>'Esgotada','completed'=>'Concluída','cancelled'=>'Cancelada'];
$campaignTone=static fn(string $status):string=>$status==='active'?'success':(in_array($status,['draft','paused','awaiting_payment'],true)?'warning':($status==='cancelled'?'danger':'neutral'));
ob_start();
?>
